            </div>
            <div className="flex-1 min-w-[160px]"><ProgressBar value={goalPct} tone={goalPct >= 100 ? 'success' : 'primary'} /></div>
            <div className="text-[11px] font-mono text-on-surface-variant shrink-0">
              {goalPct >= 100
