              </SectionCard>
            </div>

            <div className="lg:col-span-5 space-y-4">
              {/* Skill mastery */}
              <SectionCard icon={<TrendingUp className="w-4 h-4 text-primary" />} title="দক্ষতার অগ্রগতি" subtitle="Skill mastery" className="animate-fade-up stagger-2">
                <div className="space-y-3">
