                    </div>

                    {runResults[currentItem.id].status === 'ERROR' && (
                      <p className="text-rose-400 font-mono flex items-start gap-1.5">
                        <AlertCircle className="w-3.5 h-3.5 shrink-0 mt-0.5" /> {runResults[currentItem.id].error}
